81:  * Initialize a Canvas with the given width and height.
82:  */
83: 
84: Canvas::Canvas(const Napi::CallbackInfo& info) : Napi::ObjectWrap<Canvas>(info), env(info.Env()) {
85:   InstanceData* data = env.GetInstanceData<InstanceData>();
86:   ctor = Napi::Persistent(data->CanvasCtor.Value());
87: 
88:   _surface = nullptr;
89:   _closure = nullptr;
90:   width = 0;
91:   height = 0;
92:   format = CAIRO_FORMAT_ARGB32;
93: 
94:   if (info[0].IsNumber()) {
95:     uint32_t width = info[0].As<Napi::Number>().Uint32Value();
96:     uint32_t height = 0;
97: 
98:     if (info[1].IsNumber()) height = info[1].As<Napi::Number>().Uint32Value();
99: 
100:     if (width > CAIRO_MAX_SIZE) {
101:       std::string msg = "Canvas width cannot exceed " + std::to_string(CAIRO_MAX_SIZE);
102:       Napi::Error::New(env, msg).ThrowAsJavaScriptException();
103:       return;
104:     }
105: 
106:     if (height > CAIRO_MAX_SIZE) {
107:       std::string msg = "Canvas height cannot exceed " + std::to_string(CAIRO_MAX_SIZE);
108:       Napi::Error::New(env, msg).ThrowAsJavaScriptException();
109:       return;
110:     }
111: 
112:     this->width = width;
113:     this->height = height;
114: 
115:     if (info[2].IsString()) {
116:       std::string str = info[2].As<Napi::String>();
117:       if (str == "pdf") {
118:         type = CANVAS_TYPE_PDF;
119:       } else if (str == "svg") {
120:         type = CANVAS_TYPE_SVG;
121:       } else {
122:         type = CANVAS_TYPE_IMAGE;
123:       }
124:     } else {
125:       type = CANVAS_TYPE_IMAGE;
126:     }
127:   } else {
128:     type = CANVAS_TYPE_IMAGE;
129:   }
130: 
131:   cairo_status_t status = cairo_surface_status(ensureSurface());
132: 
133:   if (status != CAIRO_STATUS_SUCCESS) {
134:     Napi::Error::New(env, cairo_status_to_string(status)).ThrowAsJavaScriptException();
135:     return;
136:   }
137: }
