235: static void
236: parsePNGArgs(Napi::Value arg, PngClosure& pngargs) {
237:   if (arg.IsObject()) {
238:     Napi::Object obj = arg.As<Napi::Object>();
239:     Napi::Value cLevel;
240: 
241:     if (obj.Get("compressionLevel").UnwrapTo(&cLevel) && cLevel.IsNumber()) {
242:       uint32_t val = cLevel.As<Napi::Number>().Uint32Value();
243:       // See quote below from spec section 4.12.5.5.
244:       if (val <= 9) pngargs.compressionLevel = val;
245:     }
246: 
247:     Napi::Value rez;
248:     if (obj.Get("resolution").UnwrapTo(&rez) && rez.IsNumber()) {
249:       uint32_t val = rez.As<Napi::Number>().Uint32Value();
250:       if (val > 0) pngargs.resolution = val;
251:     }
252: 
253:     Napi::Value filters;
254:     if (obj.Get("filters").UnwrapTo(&filters) && filters.IsNumber()) {
255:       pngargs.filters = filters.As<Napi::Number>().Uint32Value();
256:     }
257: 
258:     Napi::Value palette;
259:     if (obj.Get("palette").UnwrapTo(&palette) && palette.IsTypedArray()) {
260:       Napi::TypedArray palette_ta = palette.As<Napi::TypedArray>();
261:       if (palette_ta.TypedArrayType() == napi_uint8_clamped_array) {
262:         pngargs.nPaletteColors = palette_ta.ElementLength();
263:         if (pngargs.nPaletteColors % 4 != 0) {
264:           throw "Palette length must be a multiple of 4.";
265:         }
266:         pngargs.palette = palette_ta.As<Napi::Uint8Array>().Data();
267:         pngargs.nPaletteColors /= 4;
268:         // Optional background color index:
269:         Napi::Value backgroundIndexVal;
270:         if (obj.Get("backgroundIndex").UnwrapTo(&backgroundIndexVal) && backgroundIndexVal.IsNumber()) {
271:           pngargs.backgroundIndex = backgroundIndexVal.As<Napi::Number>().Uint32Value();
272:         }
273:       }
274:     }
275:   }
276: }
277: 
278: #ifdef HAVE_JPEG
279: static void parseJPEGArgs(Napi::Value arg, JpegClosure& jpegargs) {
280:   // "If Type(quality) is not Number, or if quality is outside that range, the
281:   // user agent must use its default quality value, as if the quality argument
282:   // had not been given." - 4.12.5.5
283:   if (arg.IsObject()) {
284:     Napi::Object obj = arg.As<Napi::Object>();
285: 
286:     Napi::Value qual;
287:     if (obj.Get("quality").UnwrapTo(&qual) && qual.IsNumber()) {
288:       double quality = qual.As<Napi::Number>().DoubleValue();
289:       if (quality >= 0.0 && quality <= 1.0) {
290:         jpegargs.quality = static_cast<uint32_t>(100.0 * quality);
291:       }
292:     }
293: 
294:     Napi::Value chroma;
295:     if (obj.Get("chromaSubsampling").UnwrapTo(&chroma)) {
296:       if (chroma.IsBoolean()) {
297:         bool subsample = chroma.As<Napi::Boolean>().Value();
298:         jpegargs.chromaSubsampling = subsample ? 2 : 1;
299:       } else if (chroma.IsNumber()) {
300:         jpegargs.chromaSubsampling = chroma.As<Napi::Number>().Uint32Value();
301:       }
302:     }
303: 
304:     Napi::Value progressive;
305:     if (obj.Get("progressive").UnwrapTo(&progressive) && progressive.IsBoolean()) {
306:       jpegargs.progressive = progressive.As<Napi::Boolean>().Value();
307:     }
308:   }
309: }
310: #endif
