348: /*
349:  * Converts/encodes data to a Buffer. Async when a callback function is passed.
350: 
351:  * PDF canvases:
352:     (any) => Buffer
353:     ("application/pdf", config) => Buffer
354: 
355:  * SVG canvases:
356:     (any) => Buffer
357: 
358:  * ARGB data:
359:     ("raw") => Buffer
360: 
361:  * PNG-encoded
362:     () => Buffer
363:     (undefined|"image/png", {compressionLevel?: number, filter?: number}) => Buffer
364:     ((err: null|Error, buffer) => any)
365:     ((err: null|Error, buffer) => any, undefined|"image/png", {compressionLevel?: number, filter?: number})
366: 
367:  * JPEG-encoded
368:     ("image/jpeg") => Buffer
369:     ("image/jpeg", {quality?: number, progressive?: Boolean, chromaSubsampling?: Boolean|number}) => Buffer
370:     ((err: null|Error, buffer) => any, "image/jpeg")
371:     ((err: null|Error, buffer) => any, "image/jpeg", {quality?: number, progressive?: Boolean, chromaSubsampling?: Boolean|number})
372:  */
373: 
374: Napi::Value
375: Canvas::ToBuffer(const Napi::CallbackInfo& info) {
376:   cairo_status_t status;
377: 
378:   // Vector canvases, sync only
379:   if (isPDF() || isSVG()) {
380:     // mime type may be present, but it's not checked
381:     PdfSvgClosure* closure = static_cast<PdfSvgClosure*>(_closure);
382:     if (isPDF()) {
383: #if CAIRO_VERSION >= CAIRO_VERSION_ENCODE(1, 16, 0)
384:       if (info[1].IsObject()) { // toBuffer("application/pdf", config)
385:         setPdfMetadata(this, info[1].As<Napi::Object>());
386:       }
387: #endif // CAIRO 16+
388:     }
389: 
390:     cairo_surface_t *surf = ensureSurface();
391:     cairo_surface_finish(surf);
392: 
393:     cairo_status_t status = cairo_surface_status(surf);
394:     if (status != CAIRO_STATUS_SUCCESS) {
395:       Napi::Error::New(env, cairo_status_to_string(status)).ThrowAsJavaScriptException();
396:       return env.Undefined();
397:     }
398: 
399:     return Napi::Buffer<uint8_t>::Copy(env, &closure->vec[0], closure->vec.size());
400:   }
401: 
402:   // Raw ARGB data -- just a memcpy()
403:   if (info[0].StrictEquals(Napi::String::New(env, "raw"))) {
404:     cairo_surface_t *surface = ensureSurface();
405:     cairo_surface_flush(surface);
406:     if (nBytes() > node::Buffer::kMaxLength) {
407:       Napi::Error::New(env, "Data exceeds maximum buffer length.").ThrowAsJavaScriptException();
408:       return env.Undefined();
409:     }
410:     return Napi::Buffer<uint8_t>::Copy(env, cairo_image_surface_get_data(surface), nBytes());
411:   }
412: 
413:   // Sync PNG, default
414:   if (info[0].IsUndefined() || info[0].StrictEquals(Napi::String::New(env, "image/png"))) {
415:     try {
416:       PngClosure closure(this);
417:       parsePNGArgs(info[1], closure);
418:       if (closure.nPaletteColors == 0xFFFFFFFF) {
419:         Napi::Error::New(env, "Palette length must be a multiple of 4.").ThrowAsJavaScriptException();
420:         return env.Undefined();
421:       }
422: 
423:       status = canvas_write_to_png_stream(ensureSurface(), PngClosure::writeVec, &closure);
424: 
425:       if (!env.IsExceptionPending()) {
426:         if (status) {
427:           throw status; // TODO: throw in js?
428:         } else {
429:           // TODO it's possible to avoid this copy
430:           return Napi::Buffer<uint8_t>::Copy(env, &closure.vec[0], closure.vec.size());
431:         }
432:       }
433:     } catch (cairo_status_t ex) {
434:       CairoError(ex).ThrowAsJavaScriptException();
435:     } catch (const char* ex) {
436:       Napi::Error::New(env, ex).ThrowAsJavaScriptException();
437:     }
438: 
439:     return env.Undefined();
440:   }
441: 
442:   // Async PNG
443:   if (info[0].IsFunction() &&
444:     (info[1].IsUndefined() || info[1].StrictEquals(Napi::String::New(env, "image/png")))) {
445: 
446:     PngClosure* closure;
447:     try {
448:       closure = new PngClosure(this);
449:       parsePNGArgs(info[2], *closure);
450:     } catch (cairo_status_t ex) {
451:       CairoError(ex).ThrowAsJavaScriptException();
452:       return env.Undefined();
453:     } catch (const char* ex) {
454:       Napi::Error::New(env, ex).ThrowAsJavaScriptException();
455:       return env.Undefined();
456:     }
457: 
458:     Ref();
459:     closure->cb = Napi::Persistent(info[0].As<Napi::Function>());
460: 
461:     // Make sure the surface exists since we won't have an isolate context in the async block:
462:     ensureSurface();
463:     EncodingWorker* worker = new EncodingWorker(env);
464:     worker->Init(&ToPngBufferAsync, closure);
465:     worker->Queue();
466: 
467:     return env.Undefined();
468:   }
469: 
470: #ifdef HAVE_JPEG
471:   // Sync JPEG
472:   Napi::Value jpegStr = Napi::String::New(env, "image/jpeg");
473:   if (info[0].StrictEquals(jpegStr)) {
474:     try {
475:       JpegClosure closure(this);
476:       parseJPEGArgs(info[1], closure);
477: 
478:       write_to_jpeg_buffer(ensureSurface(), &closure);
479: 
480:       if (!env.IsExceptionPending()) {
481:         // TODO it's possible to avoid this copy.
482:         return Napi::Buffer<uint8_t>::Copy(env, &closure.vec[0], closure.vec.size());
483:       }
484:     } catch (cairo_status_t ex) {
485:       CairoError(ex).ThrowAsJavaScriptException();
486:       return env.Undefined();
487:     }
488:     return env.Undefined();
489:   }
490: 
491:   // Async JPEG
492:   if (info[0].IsFunction() && info[1].StrictEquals(jpegStr)) {
493:     JpegClosure* closure = new JpegClosure(this);
494:     parseJPEGArgs(info[2], *closure);
495: 
496:     Ref();
497:     closure->cb = Napi::Persistent(info[0].As<Napi::Function>());
498: 
499:     // Make sure the surface exists since we won't have an isolate context in the async block:
500:     ensureSurface();
501:     EncodingWorker* worker = new EncodingWorker(env);
502:     worker->Init(&ToJpegBufferAsync, closure);
503:     worker->Queue();
504:     return env.Undefined();
505:   }
506: #endif
507: 
508:   return env.Undefined();
509: }
