511: /*
512:  * Canvas::StreamPNG callback.
513:  */
514: 
515: static cairo_status_t
516: streamPNG(void *c, const uint8_t *data, unsigned len) {
517:   PngClosure* closure = (PngClosure*) c;
518:   Napi::Env env = closure->canvas->env;
519:   Napi::HandleScope scope(env);
520:   Napi::AsyncContext async(env, "canvas:StreamPNG");
521:   Napi::Value buf = Napi::Buffer<uint8_t>::Copy(env, data, len);
522:   closure->cb.MakeCallback(env.Global(), { env.Null(), buf, Napi::Number::New(env, len) }, async);
523:   return CAIRO_STATUS_SUCCESS;
524: }
