526: /*
527:  * Stream PNG data synchronously. TODO async
528:  * StreamPngSync(this, options: {palette?: Uint8ClampedArray, backgroundIndex?: uint32, compressionLevel: uint32, filters: uint32})
529:  */
530: 
531: void
532: Canvas::StreamPNGSync(const Napi::CallbackInfo& info) {
533:   if (!info[0].IsFunction()) {
534:     Napi::TypeError::New(env, "callback function required").ThrowAsJavaScriptException();
535:     return;
536:   }
537: 
538:   PngClosure closure(this);
539:   parsePNGArgs(info[1], closure);
540: 
541:   closure.cb = Napi::Persistent(info[0].As<Napi::Function>());
542: 
543:   cairo_status_t status = canvas_write_to_png_stream(ensureSurface(), streamPNG, &closure);
544: 
545:   if (!env.IsExceptionPending()) {
546:     if (status) {
547:       closure.cb.Call(env.Global(), { CairoError(status).Value() });
548:     } else {
549:       closure.cb.Call(env.Global(), { env.Null(), env.Null(), Napi::Number::New(env, 0) });
550:     }
551:   }
552: }
