561: /*
562:  * Canvas::StreamPDF callback.
563:  */
564: 
565: static cairo_status_t
566: streamPDF(void *c, const uint8_t *data, unsigned len) {
567:   PdfStreamInfo* streaminfo = static_cast<PdfStreamInfo*>(c);
568:   Napi::Env env = streaminfo->fn.Env();
569:   Napi::HandleScope scope(env);
570:   Napi::AsyncContext async(env, "canvas:StreamPDF");
571:   // TODO this is technically wrong, we're returning a pointer to the data in a
572:   // vector in a class with automatic storage duration. If the canvas goes out
573:   // of scope while we're in the handler, a use-after-free could happen.
574:   Napi::Value buf = Napi::Buffer<uint8_t>::New(env, (uint8_t *)(data), len);
575:   streaminfo->fn.MakeCallback(env.Global(), { env.Null(), buf, Napi::Number::New(env, len) }, async);
576:   return CAIRO_STATUS_SUCCESS;
577: }
