579: 
580: cairo_status_t canvas_write_to_pdf_stream(cairo_surface_t *surface, cairo_write_func_t write_func, PdfStreamInfo* streaminfo) {
581:   size_t whole_chunks = streaminfo->len / PAGE_SIZE;
582:   size_t remainder = streaminfo->len - whole_chunks * PAGE_SIZE;
583: 
584:   for (size_t i = 0; i < whole_chunks; ++i) {
585:     write_func(streaminfo, &streaminfo->data[i * PAGE_SIZE], PAGE_SIZE);
586:   }
587: 
588:   if (remainder) {
589:     write_func(streaminfo, &streaminfo->data[whole_chunks * PAGE_SIZE], remainder);
590:   }
591: 
592:   return CAIRO_STATUS_SUCCESS;
593: }
