595: /*
596:  * Stream PDF data synchronously.
597:  */
598: 
599: void
600: Canvas::StreamPDFSync(const Napi::CallbackInfo& info) {
601:   if (!info[0].IsFunction()) {
602:     Napi::TypeError::New(env, "callback function required").ThrowAsJavaScriptException();
603:     return;
604:   }
605: 
606:   if (!isPDF()) {
607:     Napi::TypeError::New(env, "wrong canvas type").ThrowAsJavaScriptException();
608:     return;
609:   }
610: 
611: #if CAIRO_VERSION >= CAIRO_VERSION_ENCODE(1, 16, 0)
612:   if (info[1].IsObject()) {
613:     setPdfMetadata(this, info[1].As<Napi::Object>());
614:   }
615: #endif
616: 
617:   cairo_surface_finish(ensureSurface());
618: 
619:   PdfSvgClosure *closure = static_cast<PdfSvgClosure *>(_closure);
620:   Napi::Function fn = info[0].As<Napi::Function>();
621:   PdfStreamInfo streaminfo;
622:   streaminfo.fn = fn;
623:   streaminfo.data = &closure->vec[0];
624:   streaminfo.len = closure->vec.size();
625: 
626:   cairo_status_t status = canvas_write_to_pdf_stream(ensureSurface(), streamPDF, &streaminfo);
627: 
628:   if (!env.IsExceptionPending()) {
