686:     Napi::Error::New(env, GENERIC_FACE_ERROR).ThrowAsJavaScriptException();
687:     return;
688:   }
689: 
690:   std::string filePath = info[0].As<Napi::String>();
691:   PangoFontDescription *sys_desc = get_pango_font_description((unsigned char *)(filePath.c_str()));
692: 
693:   if (!sys_desc) {
694:     Napi::Error::New(env, "Could not parse font file").ThrowAsJavaScriptException();
695:     return;
696:   }
697: 
698:   PangoFontDescription *user_desc = pango_font_description_new();
699: 
700:   // now check the attrs, there are many ways to be wrong
701:   Napi::Object js_user_desc = info[1].As<Napi::Object>();
702: 
703:   // TODO: use FontParser on these values just like the FontFace API works
704:   char *family = str_value(js_user_desc.Get("family"), NULL, false);
705:   char *weight = str_value(js_user_desc.Get("weight"), "normal", true);
706:   char *style = str_value(js_user_desc.Get("style"), "normal", false);
707: 
708:   if (family && weight && style) {
709:     pango_font_description_set_weight(user_desc, Canvas::GetWeightFromCSSString(weight));
710:     pango_font_description_set_style(user_desc, Canvas::GetStyleFromCSSString(style));
711:     pango_font_description_set_family(user_desc, family);
712: 
713:     auto found = std::find_if(font_face_list.begin(), font_face_list.end(), [&](FontFace& f) {
714:       return pango_font_description_equal(f.sys_desc, sys_desc);
715:     });
716: 
717:     if (found != font_face_list.end()) {
718:       pango_font_description_free(found->user_desc);
719:       found->user_desc = user_desc;
720:     } else if (register_font((unsigned char *) filePath.c_str())) {
721:       FontFace face;
722:       face.user_desc = user_desc;
723:       face.sys_desc = sys_desc;
724:       strncpy((char *)face.file_path, (char *) filePath.c_str(), 1023);
725:       font_face_list.push_back(face);
726:     } else {
727:       pango_font_description_free(user_desc);
728:       Napi::Error::New(env, "Could not load font to the system's font host").ThrowAsJavaScriptException();
729: 
730:     }
731:   } else {
732:     pango_font_description_free(user_desc);
733:     if (!env.IsExceptionPending()) {
734:       Napi::Error::New(env, GENERIC_FACE_ERROR).ThrowAsJavaScriptException();
735:     }
736:   }
737: 
738:   free(family);
739:   free(weight);
740:   free(style);
741:   fontSerial++;
742: }
