744: void
745: Canvas::DeregisterAllFonts(const Napi::CallbackInfo& info) {
746:   Napi::Env env = info.Env();
747:   // Unload all fonts from pango to free up memory
748:   bool success = true;
749: 
750:   std::for_each(font_face_list.begin(), font_face_list.end(), [&](FontFace& f) {
751:     if (!deregister_font( (unsigned char *)f.file_path )) success = false;
752:     pango_font_description_free(f.user_desc);
753:     pango_font_description_free(f.sys_desc);
754:   });
