849: /*
850:  * Given a user description, return a description that will select the
851:  * font either from the system or @font-face
852:  */
853: 
854: PangoFontDescription *
855: Canvas::ResolveFontDescription(const PangoFontDescription *desc) {
856:   // One of the user-specified families could map to multiple SFNT family names
857:   // if someone registered two different fonts under the same family name.
858:   // https://drafts.csswg.org/css-fonts-3/#font-style-matching
859:   FontFace best;
860:   istringstream families(pango_font_description_get_family(desc));
861:   unordered_set<string> seen_families;
862:   string resolved_families;
863:   bool first = true;
864: 
865:   for (string family; getline(families, family, ','); ) {
866:     string renamed_families;
867:     for (auto& ff : font_face_list) {
868:       string pangofamily = string(pango_font_description_get_family(ff.user_desc));
869:       if (streq_casein(family, pangofamily)) {
870:         const char* sys_desc_family_name = pango_font_description_get_family(ff.sys_desc);
871:         bool unseen = seen_families.find(sys_desc_family_name) == seen_families.end();
872:         bool better = best.user_desc == nullptr || pango_font_description_better_match(desc, best.user_desc, ff.user_desc);
873: 
874:         // Avoid sending duplicate SFNT font names due to a bug in Pango for macOS:
875:         // https://bugzilla.gnome.org/show_bug.cgi?id=762873
876:         if (unseen) {
877:           seen_families.insert(sys_desc_family_name);
878: 
879:           if (better) {
880:             renamed_families = string(sys_desc_family_name) + (renamed_families.size() ? "," : "") + renamed_families;
881:           } else {
882:             renamed_families = renamed_families + (renamed_families.size() ? "," : "") + sys_desc_family_name;
883:           }
884:         }
885: 
886:         if (first && better) best = ff;
887:       }
888:     }
889: 
890:     if (resolved_families.size()) resolved_families += ',';
891:     resolved_families += renamed_families.size() ? renamed_families : family;
892:     first = false;
893:   }
894: 
895:   PangoFontDescription* ret = pango_font_description_copy(best.sys_desc ? best.sys_desc : desc);
896:   pango_font_description_set_family(ret, resolved_families.c_str());
897: 
898:   return ret;
899: }
