416: /*
417:  * Load cairo surface from the image src.
418:  *
419:  * TODO: support more formats
420:  * TODO: use node IO or at least thread pool
421:  */
422: 
423: cairo_status_t
424: Image::loadSurface() {
425:   FILE *stream = fopen(filename, "rb");
426:   if (!stream) {
427:     this->errorInfo.set(NULL, "fopen", errno, filename);
428:     return CAIRO_STATUS_READ_ERROR;
429:   }
430:   uint8_t buf[5];
431:   if (1 != fread(&buf, 5, 1, stream)) {
432:     fclose(stream);
433:     return CAIRO_STATUS_READ_ERROR;
434:   }
435:   rewind(stream);
436: 
437:   // png
438:   if (isPNG(buf)) {
439:     fclose(stream);
440:     return loadPNG();
441:   }
442: 
443: 
444:   if (isGIF(buf)) {
445: #ifdef HAVE_GIF
446:     return loadGIF(stream);
447: #else
448:     this->errorInfo.set("node-canvas was built without GIF support");
449:     return CAIRO_STATUS_READ_ERROR;
450: #endif
451:   }
452: 
453:   if (isJPEG(buf)) {
454: #ifdef HAVE_JPEG
455:     return loadJPEG(stream);
456: #else
457:     this->errorInfo.set("node-canvas was built without JPEG support");
458:     return CAIRO_STATUS_READ_ERROR;
459: #endif
460:   }
461: 
462:   // confirm svg using first 1000 chars
463:   // if a very long comment precedes the root <svg> tag, isSVG returns false
464:   uint8_t head[1000] = {0};
465:   fseek(stream, 0 , SEEK_END);
466:   long len = ftell(stream);
467:   unsigned head_len = (len < 1000 ? len : 1000);
468:   unsigned head_size = head_len * sizeof(uint8_t);
469:   rewind(stream);
470:   if (head_size != fread(&head, 1, head_size, stream)) {
471:     fclose(stream);
472:     return CAIRO_STATUS_READ_ERROR;
473:   }
474:   rewind(stream);
475:   if (isSVG(head, head_len)) {
476: #ifdef HAVE_RSVG
477:     return loadSVG(stream);
478: #else
479:     this->errorInfo.set("node-canvas was built without SVG support");
480:     return CAIRO_STATUS_READ_ERROR;
481: #endif
482:   }
483: 
484:   if (isBMP(buf, 2))
485:     return loadBMP(stream);
486: 
487:   fclose(stream);
488: 
489:   this->errorInfo.set("Unsupported image type");
490:   return CAIRO_STATUS_READ_ERROR;
491: }
