507: /*
508:  * Return the alpha color for `gif` at `frame`, or -1.
509:  */
510: 
511: int
512: get_gif_transparent_color(GifFileType *gif, int frame) {
513:   ExtensionBlock *ext = gif->SavedImages[frame].ExtensionBlocks;
514:   int len = gif->SavedImages[frame].ExtensionBlockCount;
515:   for (int x = 0; x < len; ++x, ++ext) {
516:     if ((ext->Function == GRAPHICS_EXT_FUNC_CODE) && (ext->Bytes[0] & 1)) {
517:       return ext->Bytes[3] == 0 ? 0 : (uint8_t) ext->Bytes[3];
518:     }
519:   }
520:   return -1;
521: }
