523: /*
524:  * Memory GIF reader callback.
525:  */
526: 
527: int
528: read_gif_from_memory(GifFileType *gif, GifByteType *buf, int len) {
529:   gif_data_t *data = (gif_data_t *) gif->UserData;
530:   if ((data->pos + len) > data->len) len = data->len - data->pos;
531:   memcpy(buf, data->pos + data->buf, len);
532:   data->pos += len;
533:   return len;
534: }
