536: /*
537:  * Load GIF.
538:  */
539: 
540: cairo_status_t
541: Image::loadGIF(FILE *stream) {
542:   struct stat s;
543:   int fd = fileno(stream);
544: 
545:   // stat
546:   if (fstat(fd, &s) < 0) {
547:     fclose(stream);
548:     return CAIRO_STATUS_READ_ERROR;
549:   }
550: 
551:   uint8_t *buf = (uint8_t *) malloc(s.st_size);
552: 
553:   if (!buf) {
554:     fclose(stream);
555:     this->errorInfo.set(NULL, "malloc", errno);
556:     return CAIRO_STATUS_NO_MEMORY;
557:   }
558: 
559:   size_t read = fread(buf, s.st_size, 1, stream);
560:   fclose(stream);
561: 
562:   cairo_status_t result = CAIRO_STATUS_READ_ERROR;
563:   if (1 == read) result = loadGIFFromBuffer(buf, s.st_size);
564:   free(buf);
565: 
566:   return result;
567: }
