569: /*
570:  * Load give from `buf` and the given `len`.
571:  */
572: 
573: cairo_status_t
574: Image::loadGIFFromBuffer(uint8_t *buf, unsigned len) {
575:   int i = 0;
576:   GifFileType* gif;
577: 
578:   gif_data_t gifd = { buf, len, 0 };
579: 
580: #if GIFLIB_MAJOR >= 5
581:   int errorcode;
582:   if ((gif = DGifOpen((void*) &gifd, read_gif_from_memory, &errorcode)) == NULL)
583:     return CAIRO_STATUS_READ_ERROR;
584: #else
585:   if ((gif = DGifOpen((void*) &gifd, read_gif_from_memory)) == NULL)
586:     return CAIRO_STATUS_READ_ERROR;
587: #endif
588: 
589:   if (GIF_OK != DGifSlurp(gif)) {
590:     GIF_CLOSE_FILE(gif);
591:     return CAIRO_STATUS_READ_ERROR;
592:   }
593: 
594:   if (gif->SWidth > canvas_max_side || gif->SHeight > canvas_max_side) {
595:     GIF_CLOSE_FILE(gif);
596:     return CAIRO_STATUS_INVALID_SIZE;
597:   }
598: 
599:   width = naturalWidth = gif->SWidth;
600:   height = naturalHeight = gif->SHeight;
601: 
602:   uint8_t *data = new uint8_t[naturalWidth * naturalHeight * 4];
603:   if (!data) {
604:     GIF_CLOSE_FILE(gif);
605:     this->errorInfo.set(NULL, "malloc", errno);
606:     return CAIRO_STATUS_NO_MEMORY;
607:   }
608: 
609:   GifImageDesc *img = &gif->SavedImages[i].ImageDesc;
610: 
611:   // local colormap takes precedence over global
612:   ColorMapObject *colormap = img->ColorMap
613:     ? img->ColorMap
614:     : gif->SColorMap;
615: 
616:   if (colormap == nullptr) {
617:     GIF_CLOSE_FILE(gif);
618:     return CAIRO_STATUS_READ_ERROR;
619:   }
620: 
621:   int bgColor = 0;
622:   int alphaColor = get_gif_transparent_color(gif, i);
623:   if (gif->SColorMap) bgColor = (uint8_t) gif->SBackGroundColor;
624:   else if(alphaColor >= 0) bgColor = alphaColor;
625: 
626:   uint8_t *src_data = (uint8_t*) gif->SavedImages[i].RasterBits;
627:   uint32_t *dst_data = (uint32_t*) data;
628: 
629:   if (!gif->Image.Interlace) {
630:     if (naturalWidth == img->Width && naturalHeight == img->Height) {
631:       for (int y = 0; y < naturalHeight; ++y) {
632:         for (int x = 0; x < naturalWidth; ++x) {
633:           *dst_data = ((*src_data == alphaColor) ? 0 : 255) << 24
634:             | colormap->Colors[*src_data].Red << 16
635:             | colormap->Colors[*src_data].Green << 8
636:             | colormap->Colors[*src_data].Blue;
637: 
638:           dst_data++;
639:           src_data++;
640:         }
641:       }
642:     } else {
643:       // Image does not take up whole "screen" so we need to fill-in the background
644:       int bottom = img->Top + img->Height;
645:       int right = img->Left + img->Width;
646: 
647:       uint32_t bgPixel =
648:         ((bgColor == alphaColor) ? 0 : 255) << 24
649:         | colormap->Colors[bgColor].Red << 16
650:         | colormap->Colors[bgColor].Green << 8
651:         | colormap->Colors[bgColor].Blue;
652: 
653:       for (int y = 0; y < naturalHeight; ++y) {
654:         for (int x = 0; x < naturalWidth; ++x) {
655:           if (y < img->Top || y >= bottom || x < img->Left || x >= right) {
656:             *dst_data = bgPixel;
657:             dst_data++;
658:           } else {
659:             *dst_data = ((*src_data == alphaColor) ? 0 : 255) << 24
660:               | colormap->Colors[*src_data].Red << 16
661:               | colormap->Colors[*src_data].Green << 8
662:               | colormap->Colors[*src_data].Blue;
663:             dst_data++;
664:             src_data++;
665:           }
666:         }
667:       }
668:     }
669:   } else {
670:     // Image is interlaced so that it streams nice over 14.4k and 28.8k modems :)
671:     // We first load in 1/8 of the image, followed by another 1/8, followed by
672:     // 1/4 and finally the remaining 1/2.
673:     int ioffs[] = { 0, 4, 2, 1 };
674:     int ijumps[] = { 8, 8, 4, 2 };
675: 
676:     uint8_t *src_ptr = src_data;
677:     uint32_t *dst_ptr;
678: 
679:     for(int z = 0; z < 4; z++) {
680:       for(int y = ioffs[z]; y < naturalHeight; y += ijumps[z]) {
681:         dst_ptr = dst_data + naturalWidth * y;
682:         for(int x = 0; x < naturalWidth; ++x) {
683:           *dst_ptr = ((*src_ptr == alphaColor) ? 0 : 255) << 24
684:             | (colormap->Colors[*src_ptr].Red) << 16
685:             | (colormap->Colors[*src_ptr].Green) << 8
686:             | (colormap->Colors[*src_ptr].Blue);
687: 
688:           dst_ptr++;
689:           src_ptr++;
690:         }
691:       }
692:     }
693:   }
694: 
695:   GIF_CLOSE_FILE(gif);
696: 
697:   // New image surface
698:   _surface = cairo_image_surface_create_for_data(
699:       data
700:     , CAIRO_FORMAT_ARGB32
701:     , naturalWidth
702:     , naturalHeight
703:     , cairo_format_stride_for_width(CAIRO_FORMAT_ARGB32, naturalWidth));
704: 
705:   cairo_status_t status = cairo_surface_status(_surface);
706: 
707:   if (status) {
708:     delete[] data;
709:     return status;
710:   }
711: 
712:   _data = data;
713: 
714:   return CAIRO_STATUS_SUCCESS;
715: }
716: #endif /* HAVE_GIF */
