722: // libjpeg 6.2 does not have jpeg_mem_src; define it ourselves here unless
723: // libjpeg 8 is installed.
724: #if JPEG_LIB_VERSION < 80 && !defined(MEM_SRCDST_SUPPORTED)
725: 
726: /* Read JPEG image from a memory segment */
727: static void
728: init_source(j_decompress_ptr cinfo) {}
729: 
730: static boolean
731: fill_input_buffer(j_decompress_ptr cinfo) {
732:   ERREXIT(cinfo, JERR_INPUT_EMPTY);
733:   return TRUE;
734: }
735: static void
736: skip_input_data(j_decompress_ptr cinfo, long num_bytes) {
737:   struct jpeg_source_mgr* src = (struct jpeg_source_mgr*) cinfo->src;
738:   if (num_bytes > 0) {
739:     src->next_input_byte += (size_t) num_bytes;
740:     src->bytes_in_buffer -= (size_t) num_bytes;
741:   }
742: }
743: 
744: static void term_source (j_decompress_ptr cinfo) {}
745: static void jpeg_mem_src (j_decompress_ptr cinfo, void* buffer, long nbytes) {
746:   struct jpeg_source_mgr* src;
747: 
748:   if (cinfo->src == NULL) {
749:     cinfo->src = (struct jpeg_source_mgr *)
750:       (*cinfo->mem->alloc_small) ((j_common_ptr) cinfo, JPOOL_PERMANENT,
751:                                   sizeof(struct jpeg_source_mgr));
752:   }
753: 
754:   src = (struct jpeg_source_mgr*) cinfo->src;
755:   src->init_source = init_source;
756:   src->fill_input_buffer = fill_input_buffer;
757:   src->skip_input_data = skip_input_data;
758:   src->resync_to_restart = jpeg_resync_to_restart; /* use default method */
759:   src->term_source = term_source;
760:   src->bytes_in_buffer = nbytes;
761:   src->next_input_byte = (JOCTET*)buffer;
762: }
763: 
764: #endif
