766: class BufferReader : public Image::Reader {
767: public:
768:   BufferReader(uint8_t* buf, unsigned len) : _buf(buf), _len(len), _idx(0) {}
769: 
770:   bool hasBytes(unsigned n) const override { return (_idx + n - 1 < _len); }
771: 
772:   uint8_t getNext() override {
773:     return _buf[_idx++];
774:   }
775: 
776:   void skipBytes(unsigned n) override { _idx += n; }
777: 
778: private:
779:   uint8_t* _buf;  // we do not own this
780:   unsigned _len;
781:   unsigned _idx;
782: };
783: 
784: class StreamReader : public Image::Reader {
785: public:
786:   StreamReader(FILE *stream) : _stream(stream), _len(0), _idx(0) {
787:     fseek(_stream, 0, SEEK_END);
788:     _len = ftell(_stream);
789:     fseek(_stream, 0, SEEK_SET);
790:   }
791: 
792:   bool hasBytes(unsigned n) const override { return (_idx + n - 1 < _len); }
793: 
794:   uint8_t getNext() override {
795:     ++_idx;
796:     return getc(_stream);
797:   }
798: 
799:   void skipBytes(unsigned n) override {
800:     _idx += n;
801:     fseek(_stream, _idx, SEEK_SET);
802:   }
803: 
804: private:
805:   FILE* _stream;
806:   unsigned _len;
807:   unsigned _idx;
808: };
