810: void Image::jpegToARGB(jpeg_decompress_struct* args, uint8_t* data, uint8_t* src, JPEGDecodeL decode) {
811:   int stride = naturalWidth * 4;
812:   for (int y = 0; y < naturalHeight; ++y) {
813:     jpeg_read_scanlines(args, &src, 1);
814:     uint32_t *row = (uint32_t*)(data + stride * y);
815:     for (int x = 0; x < naturalWidth; ++x) {
816:       int bx = args->output_components * x;
817:       row[x] = decode(src + bx);
818:     }
819:   }
820: }
821: 
822: /*
823:  * Takes an initialised jpeg_decompress_struct and decodes the
824:  * data into _surface.
825:  */
826: 
827: cairo_status_t
828: Image::decodeJPEGIntoSurface(jpeg_decompress_struct *args, Orientation orientation) {
829:   const int channels = 4;
830:   cairo_status_t status = CAIRO_STATUS_SUCCESS;
831: 
832:   uint8_t *data = new uint8_t[naturalWidth * naturalHeight * channels];
833:   if (!data) {
834:     jpeg_abort_decompress(args);
835:     jpeg_destroy_decompress(args);
836:     this->errorInfo.set(NULL, "malloc", errno);
837:     return CAIRO_STATUS_NO_MEMORY;
838:   }
839: 
840:   uint8_t *src = new uint8_t[naturalWidth * args->output_components];
841:   if (!src) {
842:     delete[] data;
843:     jpeg_abort_decompress(args);
844:     jpeg_destroy_decompress(args);
845:     this->errorInfo.set(NULL, "malloc", errno);
846:     return CAIRO_STATUS_NO_MEMORY;
847:   }
848: 
849:   // These are the three main cases to handle. libjpeg converts YCCK to CMYK
850:   // and YCbCr to RGB by default.
851:   switch (args->out_color_space) {
852:     case JCS_CMYK:
853:       jpegToARGB(args, data, src, [](uint8_t const* src) {
854:         uint16_t k = static_cast<uint16_t>(src[3]);
855:         uint8_t r = k * src[0] / 255;
856:         uint8_t g = k * src[1] / 255;
857:         uint8_t b = k * src[2] / 255;
858:         return 255 << 24 | r << 16 | g << 8 | b;
859:       });
860:       break;
861:     case JCS_RGB:
862:       jpegToARGB(args, data, src, [](uint8_t const* src) {
863:         uint8_t r = src[0], g = src[1], b = src[2];
864:         return 255 << 24 | r << 16 | g << 8 | b;
865:       });
866:       break;
867:     case JCS_GRAYSCALE:
868:       jpegToARGB(args, data, src, [](uint8_t const* src) {
869:         uint8_t v = src[0];
870:         return 255 << 24 | v << 16 | v << 8 | v;
871:       });
872:       break;
873:     default:
874:       this->errorInfo.set("Unsupported JPEG encoding");
875:       status = CAIRO_STATUS_READ_ERROR;
876:       break;
877:   }
878: 
879:   updateDimensionsForOrientation(orientation);
880: 
881:   if (!status) {
882:     _surface = cairo_image_surface_create_for_data(
883:         data
884:       , CAIRO_FORMAT_ARGB32
885:       , naturalWidth
886:       , naturalHeight
887:       , cairo_format_stride_for_width(CAIRO_FORMAT_ARGB32, naturalWidth));
888:   }
889: 
890:   jpeg_finish_decompress(args);
891:   jpeg_destroy_decompress(args);
892:   status = cairo_surface_status(_surface);
893: 
894:   rotatePixels(data, naturalWidth, naturalHeight, channels, orientation);
895: 
896:   delete[] src;
897: 
898:   if (status) {
899:     delete[] data;
900:     return status;
901:   }
902: 
903:   _data = data;
904: 
905:   return CAIRO_STATUS_SUCCESS;
906: }
