908: /*
909:  * Callback to recover from jpeg errors
910:  */
911: 
912: static void canvas_jpeg_error_exit(j_common_ptr cinfo) {
913:   canvas_jpeg_error_mgr *cjerr = static_cast<canvas_jpeg_error_mgr*>(cinfo->err);
914:   cjerr->output_message(cinfo);
915:   // Return control to the setjmp point
916:   longjmp(cjerr->setjmp_buffer, 1);
917: }
918: 
919: // Capture libjpeg errors instead of writing stdout
920: static void canvas_jpeg_output_message(j_common_ptr cinfo) {
921:   canvas_jpeg_error_mgr *cjerr = static_cast<canvas_jpeg_error_mgr*>(cinfo->err);
922:   char buff[JMSG_LENGTH_MAX];
923:   cjerr->format_message(cinfo, buff);
924:   // (Only the last message will be returned to JS land.)
925:   cjerr->image->errorInfo.set(buff);
926: }
