928: /*
929:  * Takes a jpeg data buffer and assigns it as mime data to a
930:  * dummy surface
931:  */
932: 
933: cairo_status_t
934: Image::decodeJPEGBufferIntoMimeSurface(uint8_t *buf, unsigned len) {
935:   // TODO: remove this duplicate logic
936:   // JPEG setup
937:   struct jpeg_decompress_struct args;
938:   struct canvas_jpeg_error_mgr err;
939: 
940:   err.image = this;
941:   args.err = jpeg_std_error(&err);
942:   args.err->error_exit = canvas_jpeg_error_exit;
943:   args.err->output_message = canvas_jpeg_output_message;
944: 
945:   // Establish the setjmp return context for canvas_jpeg_error_exit to use
946:   if (setjmp(err.setjmp_buffer)) {
947:     // If we get here, the JPEG code has signaled an error.
948:     // We need to clean up the JPEG object, close the input file, and return.
949:     jpeg_destroy_decompress(&args);
950:     return CAIRO_STATUS_READ_ERROR;
951:   }
952: 
953:   jpeg_create_decompress(&args);
954: 
955:   jpeg_mem_src(&args, buf, len);
956: 
957:   jpeg_read_header(&args, 1);
958:   jpeg_start_decompress(&args);
959:   width = naturalWidth = args.output_width;
960:   height = naturalHeight = args.output_height;
961: 
962:   // Data alloc
963:   // 8 pixels per byte using Alpha Channel format to reduce memory requirement.
964:   int buf_size = naturalHeight * cairo_format_stride_for_width(CAIRO_FORMAT_A1, naturalWidth);
965:   uint8_t *data = new uint8_t[buf_size];
966:   if (!data) {
967:     this->errorInfo.set(NULL, "malloc", errno);
968:     return CAIRO_STATUS_NO_MEMORY;
969:   }
970: 
971:   BufferReader reader(buf, len);
972:   Orientation orientation = getExifOrientation(reader);
973:   updateDimensionsForOrientation(orientation);
974: 
975:   // New image surface
976:   _surface = cairo_image_surface_create_for_data(
977:       data
978:     , CAIRO_FORMAT_A1
979:     , naturalWidth
980:     , naturalHeight
981:     , cairo_format_stride_for_width(CAIRO_FORMAT_A1, naturalWidth));
982: 
983:   // Cleanup
984:   jpeg_abort_decompress(&args);
985:   jpeg_destroy_decompress(&args);
986:   cairo_status_t status = cairo_surface_status(_surface);
987: 
988:   if (status) {
989:     delete[] data;
990:     return status;
991:   }
992: 
993:   rotatePixels(data, naturalWidth, naturalHeight, 1, orientation);
994: 
995:   _data = data;
996: 
997:   return assignDataAsMime(buf, len, CAIRO_MIME_TYPE_JPEG);
998: }
