1000: /*
1001:  * Helper function for disposing of a mime data closure.
1002:  */
1003: 
1004: void
1005: clearMimeData(void *closure) {
1006:   Napi::MemoryManagement::AdjustExternalMemory(
1007:       static_cast<read_closure_t *>(closure)->env,
1008:       -static_cast<int>((static_cast<read_closure_t *>(closure)->len)));
1009:   free(static_cast<read_closure_t *>(closure)->buf);
1010:   free(closure);
1011: }
