1013: /*
1014:  * Assign a given buffer as mime data against the surface.
1015:  * The provided buffer will be copied, and the copy will
1016:  * be automatically freed when the surface is destroyed.
1017:  */
1018: 
1019: cairo_status_t
1020: Image::assignDataAsMime(uint8_t *data, int len, const char *mime_type) {
1021:   uint8_t *mime_data = (uint8_t *) malloc(len);
1022:   if (!mime_data) {
1023:     this->errorInfo.set(NULL, "malloc", errno);
1024:     return CAIRO_STATUS_NO_MEMORY;
1025:   }
1026: 
1027:   read_closure_t *mime_closure = (read_closure_t *) malloc(sizeof(read_closure_t));
1028:   if (!mime_closure) {
1029:     free(mime_data);
1030:     this->errorInfo.set(NULL, "malloc", errno);
1031:     return CAIRO_STATUS_NO_MEMORY;
1032:   }
1033: 
1034:   memcpy(mime_data, data, len);
1035: 
1036:   mime_closure->env = env;
1037:   mime_closure->buf = mime_data;
1038:   mime_closure->len = len;
1039: 
1040:   Napi::MemoryManagement::AdjustExternalMemory(env, len);
1041: 
1042:   return cairo_surface_set_mime_data(_surface
1043:     , mime_type
1044:     , mime_data
1045:     , len
1046:     , clearMimeData
1047:     , mime_closure);
1048: }
