1050: /*
1051:  * Load jpeg from buffer.
1052:  */
1053: 
1054: cairo_status_t
1055: Image::loadJPEGFromBuffer(uint8_t *buf, unsigned len) {
1056:   BufferReader reader(buf, len);
1057:   Orientation orientation = getExifOrientation(reader);
1058: 
1059:   // TODO: remove this duplicate logic
1060:   // JPEG setup
1061:   struct jpeg_decompress_struct args;
1062:   struct canvas_jpeg_error_mgr err;
1063: 
1064:   err.image = this;
1065:   args.err = jpeg_std_error(&err);
1066:   args.err->error_exit = canvas_jpeg_error_exit;
1067:   args.err->output_message = canvas_jpeg_output_message;
1068: 
1069:   // Establish the setjmp return context for canvas_jpeg_error_exit to use
1070:   if (setjmp(err.setjmp_buffer)) {
1071:     // If we get here, the JPEG code has signaled an error.
1072:     // We need to clean up the JPEG object, close the input file, and return.
1073:     jpeg_destroy_decompress(&args);
1074:     return CAIRO_STATUS_READ_ERROR;
1075:   }
1076: 
1077:   jpeg_create_decompress(&args);
1078: 
1079:   jpeg_mem_src(&args, buf, len);
1080: 
1081:   jpeg_read_header(&args, 1);
1082:   jpeg_start_decompress(&args);
1083:   width = naturalWidth = args.output_width;
1084:   height = naturalHeight = args.output_height;
1085: 
1086:   return decodeJPEGIntoSurface(&args, orientation);
1087: }
