1089: /*
1090:  * Load JPEG, convert RGB to ARGB.
1091:  */
1092: 
1093: cairo_status_t
1094: Image::loadJPEG(FILE *stream) {
1095:   cairo_status_t status;
1096: 
1097: #if defined(_MSC_VER)
1098:   if (false) { // Force using loadJPEGFromBuffer
1099: #else
1100:   if (data_mode == DATA_IMAGE) { // Can lazily read in the JPEG.
1101: #endif
1102:     Orientation orientation = NORMAL;
1103:     {
1104:     StreamReader reader(stream);
1105:     orientation = getExifOrientation(reader);
1106:     rewind(stream);
1107:     }
1108: 
1109:     // JPEG setup
1110:     struct jpeg_decompress_struct args;
1111:     struct canvas_jpeg_error_mgr err;
1112: 
1113:     err.image = this;
1114:     args.err = jpeg_std_error(&err);
1115:     args.err->error_exit = canvas_jpeg_error_exit;
1116:     args.err->output_message = canvas_jpeg_output_message;
1117: 
1118:     // Establish the setjmp return context for canvas_jpeg_error_exit to use
1119:     if (setjmp(err.setjmp_buffer)) {
1120:       // If we get here, the JPEG code has signaled an error.
1121:       // We need to clean up the JPEG object, close the input file, and return.
1122:       jpeg_destroy_decompress(&args);
1123:       return CAIRO_STATUS_READ_ERROR;
1124:     }
1125: 
1126:     jpeg_create_decompress(&args);
1127: 
1128:     jpeg_stdio_src(&args, stream);
1129: 
1130:     jpeg_read_header(&args, 1);
1131:     jpeg_start_decompress(&args);
1132: 
1133:     if (args.output_width > canvas_max_side || args.output_height > canvas_max_side) {
1134:       jpeg_destroy_decompress(&args);
1135:       return CAIRO_STATUS_INVALID_SIZE;
1136:     }
1137: 
1138:     width = naturalWidth = args.output_width;
1139:     height = naturalHeight = args.output_height;
1140: 
1141:     status = decodeJPEGIntoSurface(&args, orientation);
1142:     fclose(stream);
1143:   } else { // We'll need the actual source jpeg data, so read fully.
1144:     uint8_t *buf;
1145:     unsigned len;
1146: 
1147:     fseek(stream, 0, SEEK_END);
1148:     len = ftell(stream);
1149:     fseek(stream, 0, SEEK_SET);
1150: 
1151:     buf = (uint8_t *) malloc(len);
1152:     if (!buf) {
1153:       this->errorInfo.set(NULL, "malloc", errno);
1154:       return CAIRO_STATUS_NO_MEMORY;
1155:     }
1156: 
1157:     if (fread(buf, len, 1, stream) != 1) {
1158:       status = CAIRO_STATUS_READ_ERROR;
1159:     } else if ((DATA_IMAGE | DATA_MIME) == data_mode) {
1160:       status = loadJPEGFromBuffer(buf, len);
1161:       if (!status) status = assignDataAsMime(buf, len, CAIRO_MIME_TYPE_JPEG);
1162:     } else if (DATA_MIME == data_mode) {
1163:       status = decodeJPEGBufferIntoMimeSurface(buf, len);
1164:     }
1165: #if defined(_MSC_VER)
1166:     else if (DATA_IMAGE == data_mode) {
1167:       status = loadJPEGFromBuffer(buf, len);
1168:     }
1169: #endif
1170:     else {
1171:       status = CAIRO_STATUS_READ_ERROR;
1172:     }
1173: 
1174:     fclose(stream);
1175:     free(buf);
1176:   }
1177: 
1178:   return status;
1179: }
