1181: /*
1182:  * Returns the Exif orientation if one exists, otherwise returns NORMAL
1183:  */
1184: 
1185: Image::Orientation
1186: Image::getExifOrientation(Reader& jpeg) {
1187:   static const char kJpegStartOfImage = (char)0xd8;
1188:   static const char kJpegStartOfFrameBaseline = (char)0xc0;
1189:   static const char kJpegStartOfFrameProgressive = (char)0xc2;
1190:   static const char kJpegHuffmanTable = (char)0xc4;
1191:   static const char kJpegQuantizationTable = (char)0xdb;
1192:   static const char kJpegRestartInterval = (char)0xdd;
1193:   static const char kJpegComment = (char)0xfe;
1194:   static const char kJpegStartOfScan = (char)0xda;
1195:   static const char kJpegApp0 = (char)0xe0;
1196:   static const char kJpegApp1 = (char)0xe1;
1197: 
1198:   // Find the Exif tag (if it exists)
1199:   int exif_len = 0;
1200:   bool done = false;
1201:   while (!done && jpeg.hasBytes(1)) {
1202:     while (jpeg.hasBytes(1) && jpeg.getNext() != 0xff) {
1203:       // noop
1204:     }
1205:     if (jpeg.hasBytes(1)) {
1206:       char tag = jpeg.getNext();
1207:       switch (tag) {
1208:         case kJpegStartOfImage:
1209:           break;  // beginning of file, no extra bytes
1210:         case kJpegRestartInterval:
1211:           jpeg.skipBytes(4);
1212:           break;
1213:         case kJpegStartOfFrameBaseline:
1214:         case kJpegStartOfFrameProgressive:
1215:         case kJpegHuffmanTable:
1216:         case kJpegQuantizationTable:
1217:         case kJpegComment:
1218:         case kJpegApp0:
1219:         case kJpegApp1: {
1220:           if (jpeg.hasBytes(2)) {
1221:             uint16_t tag_len = 0;
1222:             tag_len |= jpeg.getNext() << 8;
1223:             tag_len |= jpeg.getNext();
1224:             // The tag length includes the two bytes for the length
1225:             uint16_t tag_content_len = std::max(0, tag_len - 2);
1226:             if (tag != kJpegApp1 || !jpeg.hasBytes(tag_content_len)) {
1227:               jpeg.skipBytes(tag_content_len); // skip JPEG tags we ignore.
1228:             } else if (!jpeg.hasBytes(6)) {
1229:               jpeg.skipBytes(tag_content_len); // too short to have "Exif\0\0"
1230:             } else {
1231:               if (jpeg.getNext() == 'E' && jpeg.getNext() == 'x' &&
1232:                   jpeg.getNext() == 'i' && jpeg.getNext() == 'f' &&
1233:                   jpeg.getNext() == '\0' && jpeg.getNext() == '\0') {
1234:                   exif_len = tag_content_len - 6;
1235:                   done = true;
1236:               } else {
1237:                 jpeg.skipBytes(tag_content_len); // too short to have "Exif\0\0"
1238:               }
1239:             }
1240:           } else {
1241:             done = true;  // shouldn't happen: corrupt file or we have a bug
1242:           }
1243:           break;
1244:         }
1245:         case kJpegStartOfScan:
1246:         default:
1247:             done = true;  // got to the image, apparently no exif tags here
1248:             break;
1249:       }
1250:     }
1251:   }
1252: 
1253:   // Parse exif if it exists. If it does, we have already checked that jpeglen
1254:   // is longer than exifStart + exifLen, so we can safely index the data
1255:   if (exif_len > 0) {
1256:     // The first two bytes of TIFF header are "II" if little-endian ("Intel")
1257:     // and "MM" if big-endian ("Motorola")
1258:     const bool isLE = (jpeg.getNext() == 'I');
1259:     jpeg.skipBytes(3);  // +1 for the other I/M, +2 for 0x002a
1260: 
1261:     auto readUint16Little = [](Reader &jpeg) -> uint32_t {
1262:       uint16_t val = uint16_t(jpeg.getNext());
1263:       val |= uint16_t(jpeg.getNext()) << 8;
1264:       return val;
1265:     };
1266:     auto readUint32Little = [](Reader &jpeg) -> uint32_t {
1267:       uint32_t val = uint32_t(jpeg.getNext());
1268:       val |= uint32_t(jpeg.getNext()) << 8;
1269:       val |= uint32_t(jpeg.getNext()) << 16;
1270:       val |= uint32_t(jpeg.getNext()) << 24;
1271:       return val;
1272:     };
1273:     auto readUint16Big = [](Reader &jpeg) -> uint32_t {
1274:       uint16_t val = uint16_t(jpeg.getNext()) << 8;
1275:       val |= uint16_t(jpeg.getNext());
1276:       return val;
1277:     };
1278:     auto readUint32Big = [](Reader &jpeg) -> uint32_t {
1279:       uint32_t val = uint32_t(jpeg.getNext()) << 24;
1280:       val |= uint32_t(jpeg.getNext()) << 16;
1281:       val |= uint32_t(jpeg.getNext()) << 8;
1282:       val |= uint32_t(jpeg.getNext());
1283:       return val;
1284:     };
1285:     // The first two bytes of TIFF header are "II" if little-endian ("Intel")
1286:     // and "MM" if big-endian ("Motorola")
1287:     auto readUint32 = [readUint32Little, readUint32Big, isLE](Reader &jpeg) -> uint32_t {
1288:       return isLE ? readUint32Little(jpeg) : readUint32Big(jpeg);
1289:     };
1290:     auto readUint16 = [readUint16Little, readUint16Big, isLE](Reader &jpeg) -> uint32_t {
1291:       return isLE ? readUint16Little(jpeg) : readUint16Big(jpeg);
1292:     };
1293:     // offset to the IFD0 (offset from beginning of TIFF header, II/MM,
1294:     // which is 8 bytes before where we are after reading the uint32)
1295:     jpeg.skipBytes(readUint32(jpeg) - 8);
1296: 
1297:     // Read the IFD0 ("Image File Directory 0")
1298:     // | NN |                     n entries in directory (2 bytes)
1299:     // | TT | tt | nnnn | vvvv |  entry:  tag (2b), data type (2b),
1300:     //                                    n components (4b), value/offset (4b)
1301:     if (jpeg.hasBytes(2)) {
1302:       uint16_t nEntries = readUint16(jpeg);
1303:       for (uint16_t i = 0;  i < nEntries && jpeg.hasBytes(2);  ++i) {
1304:         uint16_t tag = readUint16(jpeg);
1305:         // The entry is 12 bytes. We already read the 2 bytes for the tag.
1306:         jpeg.skipBytes(6);  // skip 2 for the data type, skip 4 n components.
1307:         if (tag == 0x112) {
1308:           switch (readUint16(jpeg)) {  // orientation tag is always one uint16
1309:             case 1: return NORMAL;
1310:             case 2: return MIRROR_HORIZ;
1311:             case 3: return ROTATE_180;
1312:             case 4: return MIRROR_VERT;
1313:             case 5: return MIRROR_HORIZ_AND_ROTATE_270_CW;
1314:             case 6: return ROTATE_90_CW;
1315:             case 7: return MIRROR_HORIZ_AND_ROTATE_90_CW;
1316:             case 8: return ROTATE_270_CW;
1317:             default: return NORMAL;
1318:           }
1319:         } else {
1320:           jpeg.skipBytes(4);  // skip the four bytes for the value
1321:         }
1322:       }
1323:     }
1324:   }
1325: 
1326:   return NORMAL;
1327: }
