1357: /*
1358:  * Rotates the pixels to the correct orientation.
1359:  */
1360: 
1361: void
1362: Image::rotatePixels(uint8_t* pixels, int width, int height, int channels,
1363:                     Orientation orientation) {
1364:   auto swapPixel = [channels](uint8_t* pixels, int src_idx, int dst_idx) {
1365:     uint8_t tmp;
1366:     for (int i = 0;  i < channels;  ++i) {
1367:       tmp = pixels[src_idx + i];
1368:       pixels[src_idx + i] = pixels[dst_idx + i];
1369:       pixels[dst_idx + i] = tmp;
1370:     }
1371:   };
1372: 
1373:   auto mirrorHoriz = [swapPixel](uint8_t* pixels, int width, int height, int channels) {
1374:     int midX = width / 2;  // ok to truncate if odd, since we don't swap a center pixel
1375:     for (int y = 0;  y < height;  ++y) {
1376:       for (int x = 0;  x < midX;  ++x) {
1377:         int orig_idx = (y * width + x) * channels;
1378:         int new_idx = (y * width + width - 1 - x) * channels;
1379:         swapPixel(pixels, orig_idx, new_idx);
1380:       }
1381:     }
1382:   };
1383: 
1384:   auto mirrorVert = [swapPixel](uint8_t* pixels, int width, int height, int channels) {
1385:     int midY = height / 2;  // ok to truncate if odd, since we don't swap a center pixel
1386:     for (int y = 0;  y < midY;  ++y) {
1387:       for (int x = 0;  x < width;  ++x) {
1388:         int orig_idx = (y * width + x) * channels;
1389:         int new_idx = ((height - y - 1) * width + x) * channels;
1390:         swapPixel(pixels, orig_idx, new_idx);
1391:       }
1392:     }
1393:   };
1394: 
1395:   auto rotate90 = [](uint8_t* pixels, int width, int height, int channels) {
1396:     const int n_bytes = width * height * channels;
1397:     uint8_t *unrotated = new uint8_t[n_bytes];
1398:     if (!unrotated) {
1399:         return;
1400:     }
1401:     std::memcpy(unrotated, pixels, n_bytes);
1402:     for (int y = 0;  y < height;  ++y) {
1403:       for (int x = 0;  x < width ;  ++x) {
1404:         int orig_idx = (y * width + x) * channels;
1405:         int new_idx = (x * height + height - 1 - y) * channels;
1406:         std::memcpy(pixels + new_idx, unrotated + orig_idx, channels);
1407:       }
1408:     }
1409:     delete[] unrotated;
1410:   };
1411: 
1412:   auto rotate270 = [](uint8_t* pixels, int width, int height, int channels) {
1413:     const int n_bytes = width * height * channels;
1414:     uint8_t *unrotated = new uint8_t[n_bytes];
1415:     if (!unrotated) {
1416:         return;
1417:     }
1418:     std::memcpy(unrotated, pixels, n_bytes);
1419:     for (int y = 0;  y < height;  ++y) {
1420:       for (int x = 0;  x < width ;  ++x) {
1421:         int orig_idx = (y * width + x) * channels;
1422:         int new_idx = ((width - 1 - x) * height + y) * channels;
1423:         std::memcpy(pixels + new_idx, unrotated + orig_idx, channels);
1424:       }
1425:     }
1426:     delete[] unrotated;
1427:   };
1428: 
1429:   switch (orientation) {
1430:     case MIRROR_HORIZ:
1431:       mirrorHoriz(pixels, width, height, channels);
1432:       break;
1433:     case MIRROR_VERT:
1434:       mirrorVert(pixels, width, height, channels);
1435:       break;
1436:     case ROTATE_180:
1437:       mirrorHoriz(pixels, width, height, channels);
1438:       mirrorVert(pixels, width, height, channels);
1439:       break;
1440:     case ROTATE_90_CW:
1441:       rotate90(pixels, height, width, channels);  // swap w/h because we need orig w/h
1442:       break;
1443:     case ROTATE_270_CW:
1444:       rotate270(pixels, height, width, channels);  // swap w/h because we need orig w/h
1445:       break;
1446:     case MIRROR_HORIZ_AND_ROTATE_90_CW:
1447:       mirrorHoriz(pixels, height, width, channels);  // swap w/h because we need orig w/h
1448:       rotate90(pixels, height, width, channels);
1449:       break;
1450:     case MIRROR_HORIZ_AND_ROTATE_270_CW:
1451:       mirrorHoriz(pixels, height, width, channels);  // swap w/h because we need orig w/h
1452:       rotate270(pixels, height, width, channels);
1453:       break;
1454:     case NORMAL:
1455:     default:
1456:       break;
1457:   }
1458: }
