1492: /*
1493:  * Renders the Rsvg handle to this image's surface
1494:  */
1495: cairo_status_t
1496: Image::renderSVGToSurface() {
1497:   cairo_status_t status;
1498: 
1499:   _surface = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, width, height);
1500: 
1501:   status = cairo_surface_status(_surface);
1502:   if (status != CAIRO_STATUS_SUCCESS) {
1503:     g_object_unref(_rsvg);
1504:     return status;
1505:   }
1506: 
1507:   cairo_t *cr = cairo_create(_surface);
1508:   status = cairo_status(cr);
1509:   if (status != CAIRO_STATUS_SUCCESS) {
1510:     g_object_unref(_rsvg);
1511:     return status;
1512:   }
1513: 
1514:   RsvgRectangle viewport = {
1515:     0, // x
1516:     0, // y
1517:     static_cast<double>(width),
1518:     static_cast<double>(height)
1519:   };
1520:   gboolean render_ok = rsvg_handle_render_document(_rsvg, cr, &viewport, nullptr);
1521:   if (!render_ok) {
1522:     g_object_unref(_rsvg);
1523:     cairo_destroy(cr);
1524:     return CAIRO_STATUS_READ_ERROR; // or WRITE?
1525:   }
1526: 
1527:   cairo_destroy(cr);
1528: 
1529:   _svg_last_width = width;
1530:   _svg_last_height = height;
1531: 
1532:   return status;
1533: }
