1536:  * Load SVG
1537:  */
1538: 
1539: cairo_status_t
1540: Image::loadSVG(FILE *stream) {
1541:   _is_svg = true;
1542: 
1543:   struct stat s;
1544:   int fd = fileno(stream);
1545: 
1546:   // stat
1547:   if (fstat(fd, &s) < 0) {
1548:     fclose(stream);
1549:     return CAIRO_STATUS_READ_ERROR;
1550:   }
1551: 
1552:   uint8_t *buf = (uint8_t *) malloc(s.st_size);
1553: 
1554:   if (!buf) {
1555:     fclose(stream);
1556:     return CAIRO_STATUS_NO_MEMORY;
1557:   }
1558: 
1559:   size_t read = fread(buf, s.st_size, 1, stream);
1560:   fclose(stream);
1561: 
1562:   cairo_status_t result = CAIRO_STATUS_READ_ERROR;
1563:   if (1 == read) result = loadSVGFromBuffer(buf, s.st_size);
1564:   free(buf);
1565: 
1566:   return result;
1567: }
