1571: /*
1572:  * Load BMP from buffer.
1573:  */
1574: 
1575: cairo_status_t Image::loadBMPFromBuffer(uint8_t *buf, unsigned len){
1576:   BMPParser::Parser parser;
1577: 
1578:   // Reversed ARGB32 with pre-multiplied alpha
1579:   uint8_t pixFmt[5] = {2, 1, 0, 3, 1};
1580:   parser.parse(buf, len, pixFmt);
1581: 
1582:   if (parser.getStatus() != BMPParser::Status::OK) {
1583:     errorInfo.reset();
1584:     errorInfo.message = parser.getErrMsg();
1585:     return CAIRO_STATUS_READ_ERROR;
1586:   }
