Image::Image(const Napi::CallbackInfo& info) : ObjectWrap<Image>(info), env(info.Env()) {
  data_mode = DATA_IMAGE;
  info.This().ToObject().Unwrap().Set("onload", env.Null());
  info.This().ToObject().Unwrap().Set("onerror", env.Null());
  filename = NULL;
  _data = nullptr;
